def isThree(n):
    # 1 cannot have three divisors
    if n == 1:
        return False

    # Compute integer square root
    s = int(n ** 0.5)
    if s * s != n:
        return False  # Not a perfect square

    # Check if s is a prime number
    if s < 2:
        return False
    for i in range(2, int(s ** 0.5) + 1):
        if s % i == 0:
            return False
    # n is the square of a prime number
    return True
